import React, { useState } from 'react';
import { User, Github, Save, Globe } from 'lucide-react';

const ProfilePage = () => {
  // 1. نضع البيانات الأولية داخل الـ State
  const [profileData, setProfileData] = useState({
    name: '',
    bio: '',
    github: '',
    portfolio: ''
  });

  // 2. دالة لتحديث البيانات عند الكتابة في أي حقل
  const handleChange = (e) => {
    const { name, value } = e.target;
    setProfileData({
      ...profileData, // نحتفظ بالبيانات القديمة
      [name]: value   // نحدث فقط الحقل الذي تغير
    });
  };

  const handleSave = () => {
    // هنا مستقبلاً ستقوم بإرسال profileData إلى الـ Database (Node.js/Express)
    console.log("تم حفظ البيانات بنجاح:", profileData);
    alert("تم حفظ التعديلات!");
  };

  return (
    <div style={{ padding: '40px', direction: 'rtl', backgroundColor: '#fdfbff', minHeight: '100vh' }}>
      <div style={{ maxWidth: '600px', margin: '0 auto', backgroundColor: 'white', padding: '30px', borderRadius: '15px', boxShadow: '0 5px 15px rgba(0,0,0,0.05)' }}>
        
        <h2 style={{ color: '#4a3f6b', marginBottom: '20px' }}>تعديل الملف الشخصي</h2>

        {/* حقل الاسم */}
        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px' }}>الاسم الكامل:</label>
          <input 
            type="text" 
            name="name" // يجب أن يطابق الاسم في الـ state
            value={profileData.name} 
            onChange={handleChange} // هنا يحدث السحر!
            style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #ddd' }}
            placeholder="أدخل اسمك هنا..."
          />
        </div>

        {/* حقل نبذة تعريفية */}
        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px' }}>نبذة عنك:</label>
          <textarea 
            name="bio"
            value={profileData.bio}
            onChange={handleChange}
            style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #ddd', height: '80px' }}
            placeholder="اكتب شيئاً عن مهاراتك..."
          />
        </div>

        {/* حقل GitHub */}
        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px' }}>رابط GitHub:</label>
          <input 
            type="text" 
            name="github"
            value={profileData.github}
            onChange={handleChange}
            style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #ddd' }}
          />
        </div>

        {/* زر الحفظ */}
        <button 
          onClick={handleSave}
          style={{ width: '100%', backgroundColor: '#4a3f6b', color: 'white', padding: '12px', borderRadius: '10px', border: 'none', cursor: 'pointer', fontWeight: 'bold', marginTop: '10px' }}
        >
          <Save size={18} style={{ marginLeft: '8px' }} /> حفظ التغييرات في القاعدة
        </button>

      </div>
    </div>
  );
};

export default ProfilePage;
